    "     * at byte 2r of it, and the bit count is 16 * nunits. */\n"
    "    uint r = nunits & 31u;\n"
    "    M[r >> 1] |= 0x80u << ((r & 1u) * 16u);\n"
    "    if (r * 2u < 56u) {\n"
    "        M[14] = nunits << 4;\n"
    "        M[15] = nunits >> 28;\n"
    "        md4_compress_md4utf16(h4[0], h4[1], h4[2], h4[3], M);\n"
    "    } else {\n"
    "        md4_compress_md4utf16(h4[0], h4[1], h4[2], h4[3], M);\n"
    "        for (int j = 0; j < 16; j++) M[j] = 0u;\n"
    "        M[14] = nunits << 4;\n"
    "        M[15] = nunits >> 28;\n"
    "        md4_compress_md4utf16(h4[0], h4[1], h4[2], h4[3], M);\n"
    "    }\n"
    "    return nunits;\n"
    "}\n"
    "\n"
    "/* template_finalize: MD4UTF16 = MD4(iconv(UTF-8 -> UTF-16LE)(input)),\n"
    " * which is the ONLY variant CPU JOB_MD4UTF16 computes.\n"
    " *\n"
    " * THE NO-DIGEST CASES.  The CPU guard, mdxfind.c 1.616, is\n"
    " *\n"
    " *     len = U8TO16LE(cur, len, wline, MAXLINE*2);\n"
    " *     if (len <= 0)\n"
    " *       break;                       -- no digest AT ALL for this candidate\n"
    " *\n"
    " * and `len <= 0` is true for TWO reasons, both of which land on live = 0:\n"
    " * the conversion FAILED (utf8_to_utf16() returned a negative RULE32_ERR_\n"
    " * because the candidate is not well-formed UTF-8) or it produced NOTHING\n"
    " * (the candidate was empty).  Before 1.616 the guard was iconv's\n"
    " * `ic_outleft == MAXLINE*2`, which tested only the second; the shortened\n"
    " * //IGNORE reading of an ill-formed candidate WAS hashed and probed.\n"
    " *\n"
    " * Getting the empty case wrong is not a miss, it is a FALSE POSITIVE, and\n"
    " * a spectacularly likely one: it would otherwise hash to MD4 of the empty\n"
    " * string, 31d6cfe0d16ae931b73c59d7e0c089c0, which is the empty password\n"
    " * and is present in essentially every NTLM-family hash list.  The kernel\n"
    " * would have reported garbage bytes as the plaintext for it.  Getting the\n"
    " * ill-formed case wrong is a false positive too, just a less uniform one:\n"
    " * it reports the digest of a candidate with bytes deleted, labelled with\n"
    " * the plaintext that was NOT hashed.\n"
    " *\n"
    " * live is NOT re-armed by template_iterate: the CPU's break leaves the\n"
    " * whole case, so iterations 2..Maxiter produce nothing either.  Tested\n"
    " * directly at -i 3 (8 well-formed + 8 ill-formed candidates): CPU and GPU\n"
    " * both emit 24 digests, 8 candidates x 3 iterations, and the 12 ladder\n"
    " * digests reachable only from a //IGNORE partial are emitted by neither.\n"
    " * The ladder itself is untouched by the refusal change -- template_iterate\n"
    " * feeds 32 lowercase hex characters, which are ASCII, so there is nothing\n"
    " * for a UTF-8 validator to reject past iteration 1. */\n"
    "static inline void template_finalize(thread template_state &st,\n"
    "                                device const uchar *data,\n"
    "                                int len)\n"
    "{\n"
    "    int dropped;\n"
    "    uint nunits = md4_over_utf16le(st.h, data, len, dropped);\n"
    "    st.live = (!dropped && nunits != 0u) ? 1u : 0u;\n"
    "}\n"
    "\n"
    "/* template_iterate: -i loop step. CPU reference at mdxfind.c:15059-15066:\n"
    " *\n"
    " *   prmd5(md5buf.h, mdbuf, 32);     // 32 lowercase hex chars in mdbuf\n"
    " *   to_utf16le(mdbuf, linebuf, 32); // 64 UTF-16LE bytes (each ASCII byte\n"
    " *                                   //   followed by 0x00)\n"
    " *   MD4(linebuf, 64, md5buf.h);     // MD4 over the 64-byte buffer\n"
    " *\n"
    " * Implementation:\n"
    " *   1. Pack lowercase hex of state into 8 LE uint32 words via md5_to_hex_lc\n"
    " *      (defined in gpu_common.cl). Result: M_hex[0..7] each holds 4 hex\n"
    " *      bytes in LE order.\n"
    " *   2. Build the FIRST MD4 block from those 32 hex bytes via UTF-16LE\n"
    " *      zero-extend pack: M_blk[j] = hex[2j] | (hex[2j+1] << 16) for j in\n"
    " *      0..15. Read hex bytes from M_hex via byte extraction.\n"
    " *      Reset state IV, MD4-compress this first block.\n"
    " *   3. Build the SECOND MD4 block: M[0] = 0x80 pad marker (UTF-16 byte\n"
    " *      position 64 = wi=0 of block 2), M[1..13] = 0, M[14] = 64*8 = 512\n"
    " *      (bit count for 64 UTF-16LE bytes), M[15] = 0. MD4-compress. */\n"
    "static inline void template_iterate(thread template_state &st)\n"
    "{\n"
    "    uint M_hex[16];\n"
    "    /* Step 1: lowercase-hex of current digest -> M_hex[0..7] (32 bytes).\n"
    "     * md5_to_hex_lc writes M[0..7] LE-packed; M[8..15] are not touched\n"
    "     * by md5_to_hex_lc but our local M_hex was uninitialized -- ok,\n"
    "     * we only read indices [0..7] below. */\n"
    "    md5_to_hex_lc(st.h[0], st.h[1], st.h[2], st.h[3], M_hex);\n"
    "\n"
    "    /* Step 2: build first MD4 block over UTF-16LE-zero-extend of the 32\n"
    "     * hex chars. Hex char k is at byte position k of the linear hex\n"
    "     * stream, which is at M_hex[k>>2], byte (k&3) (LE order). */\n"
    "    uint M_blk[16];\n"
    "    for (int j = 0; j < 16; j++) {\n"
    "        int k0 = j * 2;          /* hex char index for low half of M_blk[j] */\n"
    "        int k1 = j * 2 + 1;      /* hex char index for high half of M_blk[j] */\n"
    "        uint c0 = (M_hex[k0 >> 2] >> ((k0 & 3) * 8)) & 0xffu;\n"
    "        uint c1 = (M_hex[k1 >> 2] >> ((k1 & 3) * 8)) & 0xffu;\n"
    "        M_blk[j] = c0 | (c1 << 16);\n"
    "    }\n"
    "    /* Reset state to MD4 IV before consuming the new input. */\n"
    "    st.h[0] = 0x67452301u;\n"
    "    st.h[1] = 0xEFCDAB89u;\n"
    "    st.h[2] = 0x98BADCFEu;\n"
    "    st.h[3] = 0x10325476u;\n"
    "    md4_compress_md4utf16(st.h[0], st.h[1], st.h[2], st.h[3], M_blk);\n"
    "\n"
    "    /* Step 3: build second MD4 block (pad + length). UTF-16 byte 64 lands\n"
    "     * at wi=0, bi=0 of block 2 -- so M[0] = 0x80 (low byte of word 0). */\n"
    "    M_blk[0] = 0x80u;\n"
    "    for (int j = 1; j < 14; j++) M_blk[j] = 0u;\n"
    "    M_blk[14] = 64u * 8u;        /* 64 UTF-16LE bytes = 512 bits */\n"
    "    M_blk[15] = 0u;\n"
    "    md4_compress_md4utf16(st.h[0], st.h[1], st.h[2], st.h[3], M_blk);\n"
    "}\n"
    "\n"
    "static inline int template_digest_compare(thread const template_state &st,\n"
    "                                device const uint *compact_fp,\n"
    "                                device const uint *compact_idx,\n"
    "                                ulong compact_mask,\n"
    "                                uint max_probe,\n"
    "                                uint hash_data_count,\n"
    "                                device const uchar *hash_data_buf,\n"
    "                                device const ulong *hash_data_off,\n"
    "                                device const ulong *overflow_keys,\n"
    "                                device const uchar *overflow_hashes,\n"
    "                                device const uint *overflow_offsets,\n"
    "                                uint overflow_count,\n"
    "                                thread uint *out_idx)\n"
    "{\n"
    "    if (!st.live) return 0;\n"
    "    return probe_compact_idx(\n"
    "        st.h[0], st.h[1], st.h[2], st.h[3],\n"
    "        compact_fp, compact_idx,\n"
    "        compact_mask, max_probe, hash_data_count,\n"
    "        hash_data_buf, hash_data_off,\n"
    "        overflow_keys, overflow_hashes, overflow_offsets, overflow_count,\n"
    "        out_idx);\n"
    "}\n"
    "\n"
    "\n"
    "#define template_emit_hit_or_overflow(hits, hit_count, max_hits, st, widx, sidx, iter, \\\n"
    "                                      hashes_shown, matched_idx, dedup_mask, \\\n"
    "                                      ovr_set, ovr_gid, lane_gid) \\\n"
    "    EMIT_HIT_4_DEDUP_OR_OVERFLOW((hits), (hit_count), (max_hits), \\\n"
    "               (widx), (sidx), (iter), \\\n"
    "               (st).h[0], (st).h[1], (st).h[2], (st).h[3], \\\n"
    "               (hashes_shown), (matched_idx), (dedup_mask), \\\n"
    "               (ovr_set), (ovr_gid), (lane_gid))\n"
;
